characterManager.onPLChanged = () => { plCache.dirty = true; };

// ----- Automatic Zenkai-on-full-heal hook -----
// Whenever a character's HP changes and lands on MAX HP, any pending Zenkai fires automatically
// (the bonus applies and is queued; handlers surface it via takeZenkaiNotice(userId)).
// NOTICES ARE PER-USER so another player's zenkai never shows up on your own character-view.
const zenkaiNoticeQueue = new Map(); // userId -> queued notice text

// Zenkai is limited to 3 charges per saga, and leaves the Saiyan exhausted for 24h.
const ZENKAI_CHARGES_PER_SAGA = 3;
const ZENKAI_EXHAUST_MS = 24 * 60 * 60 * 1000;

function getZenkaiCharges(character) {
    if (!character) return 0;
    if (character.zenkaiSaga !== globalSaga) {
        character.zenkaiSaga = globalSaga;
        character.zenkaiCharges = ZENKAI_CHARGES_PER_SAGA;
    }
    return (character.zenkaiCharges == null ? ZENKAI_CHARGES_PER_SAGA : character.zenkaiCharges);
}

function checkAndQueueZenkai(userId) {
    try {
        const c = characterManager.getCharacter(userId);
        if (!c) return;
        const msg = checkPendingZenkai(userId, c);
        const cmpMsg = applyCompanionZenkai(c);
        if (cmpMsg) characterManager.saveCharacters();
        const combined = (msg || '') + (cmpMsg || '');
        if (combined) zenkaiNoticeQueue.set(userId, (zenkaiNoticeQueue.get(userId) || '') + combined);
    } catch (e) {}
}

// Apply any banked companion Zenkai (survived near death in a battle) to the companion's stats.
// Companions are at full HP between battles, so a pending Zenkai fires on the next full-HP check.
function applyCompanionZenkai(ownerChar) {
    if (!ownerChar || !Array.isArray(ownerChar.companions)) return '';
    let text = '';
    ownerChar.companions.forEach(cmp => {
        if (!cmp || !cmp.zenkaiPending) return;
        const pending = cmp.zenkaiPending;
        const points = Math.max(1, Math.ceil((pending.powerLevel || 1) * pending.gainPercent / 100));
        const stats = { ...(cmp.stats || {}) };
        const distribution = distributeGain(points, ['str', 'dex', 'con', 'wil', 'spi']);
        Object.entries(distribution).forEach(([stat, value]) => {
            stats[stat] = (stats[stat] || 0) + value;
        });
        cmp.stats = stats;
        cmp.zenkaiPending = null;
        text += `\n✨ **${cmp.name}** (companion) triggered a **ZENKAI**! **+${points}** stat points!`;
    });
    return text;
}

function takeZenkaiNotice(userId) {
    if (!userId) return '';
    const n = zenkaiNoticeQueue.get(userId) || '';
    if (!n) return '';
    // Only surface the zenkai once the character is actually at FULL HP (rest/midnight must heal to full).
    const c = characterManager.getCharacter(userId);
    if (!c || (c.currentHP || 0) < (c.maxHP || 1)) return '';
    zenkaiNoticeQueue.delete(userId);
    return n;
}

// A queued per-user notice that a child was born. Surfaced on the player's next supported action
// (character-view, rest, etc.) so they know to name the new baby with /name-child.
const birthNoticeQueue = new Map(); // userId -> queued birth notice text

function queueBirthNotice(userId, text) {
    if (!userId || !text) return;
    birthNoticeQueue.set(userId, (birthNoticeQueue.get(userId) || '') + text);
}

function takeBirthNotice(userId) {
    if (!userId) return '';
    const n = birthNoticeQueue.get(userId) || '';
    if (!n) return '';
    birthNoticeQueue.delete(userId);
    return n;
}

const _origUpdateCharacter = characterManager.updateCharacter.bind(characterManager);
characterManager.updateCharacter = function (userId, characterId, updates) {
    const result = _origUpdateCharacter(userId, characterId, updates);
    checkAndQueueZenkai(userId);
    return result;
};

const _origModifyHP = characterManager.modifyHP.bind(characterManager);
characterManager.modifyHP = function (userId, characterId, amount) {
    const result = _origModifyHP(userId, characterId, amount);
    checkAndQueueZenkai(userId);
    return result;
};

// Register a slash command by collecting it into a deploy list (see deployCommands below).
const COMMANDS_TO_DEPLOY = [];
function registerCommand(command) {
    COMMANDS_TO_DEPLOY.push(command);
}

// Bulk-reset this guild's (or the global) command set. `.set(COMMANDS_TO_DEPLOY)` atomically
// replaces the WHOLE command list, so new commands (e.g. /feed-baby, /mine) appear and stale/
// renamed commands are removed on every startup.
async function deployCommands() {
    if (COMMANDS_TO_DEPLOY.length === 0) return;
    try {
        if (guildId) {
            const guild = client.guilds.cache.get(guildId);
            if (guild) {
                await guild.commands.set(COMMANDS_TO_DEPLOY);
                console.log(`[deploy] Registered ${COMMANDS_TO_DEPLOY.length} guild commands: ${COMMANDS_TO_DEPLOY.map(c => c.name).join(', ')}`);
                return;
            }
        }
        await client.application.commands.set(COMMANDS_TO_DEPLOY);
        console.log(`[deploy] Registered ${COMMANDS_TO_DEPLOY.length} global commands: ${COMMANDS_TO_DEPLOY.map(c => c.name).join(', ')}`);
    } catch (err) {
        console.error('[deploy] Failed to deploy commands:', err && err.message ? err.message : err);
    }
}

