// Mentor style table (1d10; Karate added from the board)
const MENTOR_STYLE_ORDER = ['Swordsman', 'Legionary Discipline', 'Turtle', 'Crane', 'Wolf', 'Wrestler', 'Boxing', 'Tiger', 'Taekwondo', 'Karate', 'Assassin'];

// Techniques each mentor style can teach (from the style cards' Abilities lists)
const MENTOR_STYLES = {
    'Swordsman': { name: 'Swordsman Mentor', moves: ['Cross Slash', 'Ki Sharpening', 'Impaling Thrust'] },
    'Legionary Discipline': { name: 'Legionary Mentor', moves: ['Sweeping Swing', 'Thrusting Strikes', 'Lacerating Slash'] },
    'Turtle': { name: 'Turtle Hermit Mentor', moves: ['Kamehameha', 'Kamehameha Surge', 'Dashing Kamehameha', 'Destructo Disc'] },
    'Crane': { name: 'Crane Master Mentor', moves: ['Dodon Ray', 'Dodon Barrage', 'Machine Gun Punches'] },
    'Wolf': { name: 'Wolf Master Mentor', moves: ['Wolf Fang Fist', 'Whirlwind Kick', 'Neo Wolf Fang Fist'] },
    'Wrestler': { name: 'Wrestler Mentor', moves: ['Clothesline', 'Arm Crusher', 'Choke Slam', 'Suplex', 'Groundslam', 'Shove'] },
    'Boxing': { name: 'Boxing Mentor', moves: ['One-Two', 'Liver Punch', 'Corkscrew'] },
    'Tiger': { name: 'Tiger Master Mentor', moves: ['Savage Elbow', 'Feral Fury Knee', 'Tiger Teep', 'Leaping Tiger Fist'] },
    'Taekwondo': { name: 'Taekwondo Mentor', moves: ['Crashing Thunder Kick', 'Tornado Roundhouse', "Heaven's Howl"] },
    'Karate': { name: 'Karate Mentor', moves: ['Gyaku-Zuki', 'Mae-Geri', 'Uraken', 'Shuto-Uchi'] },
    'Assassin': { name: 'Assassin Mentor', moves: ['Assassinate', 'Pin-Point Blow', 'Incognito', 'Secret Poison'] },
    'Shogun': { name: 'Shogun Mentor', moves: ['Rising Sun Technique', 'Sweeping Sunlight', 'Early Morning', 'Crimson Sky Flurry'] },
    // Maniac has no signature techniques — it's a passive-based style (Sadist Limit, etc.), so it grants no moves.
    'Maniac': { name: 'Maniac', moves: [] }
};

// Techniques a mentor teaches individually that are NOT part of their fighting style (e.g. the
// Turtle mentor's Pump Up). These can be learned from the mentor directly without adopting the
// style, and are NOT granted just by adopting the style. Style signature moves (the `moves`
// arrays above) are the ONLY way to get that style's techniques — they are never taught alone.
const MENTOR_SPECIFIC_TECHNIQUES = {
    'Turtle': ['Pump Up']
};

const MENTOR_GENERAL_TEACHINGS = [
    { id: 'fly', type: 'technique', technique: 'Fly', label: '🕊️ Learn Fly' },
    { id: 'ki_sense', type: 'technique', technique: 'Ki Sense', label: '👁️ Learn Ki Sense' },
    { id: 'ki_efficiency', type: 'kiEfficiency', label: '🔋 Learn Ki Efficiency' },
    { id: 'ki_application', type: 'kiApplication', label: '💥 Learn Ki Application' }
];

function getKnownTechniqueNames(character) {
    return Array.isArray(character && character.techniques)
        ? character.techniques.map(t => String(typeof t === 'string' ? t : (t.name || t)))
        : [];
}

function hasKiEfficiency(character) {
    if (!character) return false;
    return character.mutation === 'Wise Old One'
        || character.kiEfficiency === true
        || (typeof character.kiEfficiency === 'number' && character.kiEfficiency > 0);
}

function getKiEfficiencyMastery(character) {
    if (!hasKiEfficiency(character)) return 0;
    if (character.mutation === 'Wise Old One') return 3;
    return Math.max(0, Math.min(3, Number((character.abilityMastery || {})['Ki Efficiency']) || 0));
}

// Dragonball DND: base +1 SPI; mastery raises the stat bonuses at levels 1–3.
function getKiEfficiencyEffects(character) {
    if (!hasKiEfficiency(character)) return { spi: 0, wil: 0 };

    const mastery = getKiEfficiencyMastery(character);
    if (mastery >= 3) return { spi: 5, wil: 2 };
    if (mastery === 2) return { spi: 3, wil: 1 };
    if (mastery === 1) return { spi: 2, wil: 0 };
    return { spi: 1, wil: 0 };
}

function hasKiApplication(character) {
    return !!(character && (character.kiApplication === true || (typeof character.kiApplication === 'number' && character.kiApplication > 0)));
}

function getKiApplicationMastery(character) {
    if (!hasKiApplication(character)) return 0;
    return Math.max(0, Math.min(3, Number((character.abilityMastery || {})['Ki Application']) || 0));
}

// Ki Application: an active ability until mastery 3 (then passive, free). Returns per-turn Ki cost,
// flat attack-damage bonus, DEX bonus while active, and whether it's passive.
// `effectiveWilMod` (optional): the character's EFFECTIVE WIL modifier — the same mod combat rolls
// use (raw stat curve + stat multipliers + form scaling + wielded/worn gear + modBonus). Mastery 3's
// passive +1/4 WIL mod bonus must derive from it, not from the raw character WIL stat.
function getKiApplicationEffects(character, effectiveWilMod = null) {
    if (!hasKiApplication(character)) return { cost: 0, damage: 0, dex: 0, passive: false, wilDamage: 0 };
    const mastery = getKiApplicationMastery(character);
    // Mastery 3: passive & free, adds 1/4 WIL MOD (not the raw WIL stat) to attack damage.
    if (mastery >= 3) {
        const wilMod = (effectiveWilMod != null && Number.isFinite(Number(effectiveWilMod)))
            ? Number(effectiveWilMod)
            : calculateModifier((character.stats && character.stats.wil) || 0);
        const bonus = Math.max(0, Math.floor(wilMod / 4));
        return { cost: 0, damage: bonus, dex: 0, passive: true, wilDamage: bonus };
    }
    if (mastery === 2) return { cost: 2, damage: 5, dex: 4, passive: false, wilDamage: 0 };
    if (mastery === 1) return { cost: 3, damage: 4, dex: 3, passive: false, wilDamage: 0 };
    return { cost: 5, damage: 3, dex: 3, passive: false, wilDamage: 0 };
}

// Does this character know a given combat technique? Some abilities (Ki Application, Ki
// Efficiency) are tracked on their own flags rather than always living in the techniques array.
function characterKnowsTechnique(character, name) {
    if (!character) return false;
    if (Array.isArray(character.techniques) && character.techniques.includes(name)) return true;
    if (name === 'Ki Application') return hasKiApplication(character);
    if (name === 'Ki Efficiency') return hasKiEfficiency(character);
    return false;
}

function getMentorRewardChoices(character, mentorStyle) {
    const mentor = MENTOR_STYLES[mentorStyle];
    if (!mentor || !character) return [];

    const known = getKnownTechniqueNames(character);
    const choices = [];

    // A character can equip one style at a time; picking this replaces their current one.
    // Adopting the style grants ALL of that style's techniques automatically.
    if (character.fightingStyle !== mentorStyle) {
        // Assassin requires -250 negative alignment — you can still fight/beat the mentor,
        // you just can't adopt that style (Trello "Assassin" card).
        const styleEligible = mentorStyle !== 'Assassin' || getPlayerAlignmentValue(character) <= -250;
        if (styleEligible) {
            choices.push({
                id: 'style',
                type: 'style',
                style: mentorStyle,
                label: `🥋 Adopt ${mentorStyle} Style (grants all its techniques)`
            });
        }
    }

    MENTOR_GENERAL_TEACHINGS.forEach(teaching => {
        if (teaching.type === 'technique' && !known.includes(teaching.technique)) {
            choices.push({ ...teaching });
        }
        if (teaching.type === 'kiEfficiency' && !hasKiEfficiency(character)) {
            choices.push({ ...teaching });
        }
        if (teaching.type === 'kiApplication' && !hasKiApplication(character)) {
            choices.push({ ...teaching });
        }
    });

    // A mentor can't teach individual style signature moves — those are ONLY gained by adopting
    // the style. Mentor-specific techniques (e.g. the Turtle mentor's Pump Up) are taught alone.
    (MENTOR_SPECIFIC_TECHNIQUES[mentorStyle] || []).forEach(move => {
        if (!known.includes(move)) {
            choices.push({ id: `technique_${move}`, type: 'technique', technique: move, label: `🧠 Learn ${move}` });
        }
    });

    return choices;
}

function buildMentorRewardComponents(userId, choices) {
    const rows = [];
    for (let index = 0; index < choices.length; index += 5) {
        const row = new ActionRowBuilder();
        choices.slice(index, index + 5).forEach((choice, offset) => {
            row.addComponents(
                new ButtonBuilder()
                    .setCustomId(`mentor_reward_${userId}_${index + offset}`)
                    .setLabel(choice.label)
                    .setStyle(choice.type === 'style' ? ButtonStyle.Primary : ButtonStyle.Success)
            );
        });
        rows.push(row);
    }
    // Offer to teach a companion instead of the player (if they have any).
    const character = characterManager.getCharacter(userId);
    const companions = (character && Array.isArray(character.companions)) ? character.companions.filter(c => !c.isChild) : [];
    if (companions.length > 0) {
        rows.push(new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId('mentor_teach_cmp')
                .setLabel('🥋 Teach a Companion')
                .setStyle(ButtonStyle.Secondary)
        ));
    }
    return rows;
}

// Lessons a mentor can give a companion: only the whole style (which grants all of its
// techniques). A mentor can't teach a companion a single style move — just the style.
function getCompanionTeachingChoices(companion, mentorStyle, ownerChar) {
    const mentor = MENTOR_STYLES[mentorStyle];
    if (!mentor || !companion) return [];
    const choices = [];
    // Assassin style keeps its -250 alignment requirement (Trello "Assassin" card).
    const styleEligible = mentorStyle !== 'Assassin' || (ownerChar && getPlayerAlignmentValue(ownerChar) <= -250);
    if (companion.fightingStyle !== mentorStyle && styleEligible) {
        choices.push({ id: 'style', type: 'style', style: mentorStyle, label: `🥋 Adopt ${mentorStyle} Style (grants all its techniques)` });
    }
    return choices;
}

function buildCompanionPickerComponents(companions) {
    const rows = [];
    for (let index = 0; index < companions.length; index += 5) {
        const row = new ActionRowBuilder();
        companions.slice(index, index + 5).forEach((cmp, offset) => {
            row.addComponents(
                new ButtonBuilder()
                    .setCustomId(`mentor_teach_cmp_pick_${index + offset}`)
                    .setLabel(cmp.name)
                    .setStyle(ButtonStyle.Secondary)
            );
        });
        rows.push(row);
    }
    return rows;
}

function buildCompanionTeachingComponents(choices) {
    const rows = [];
    for (let index = 0; index < choices.length; index += 5) {
        const row = new ActionRowBuilder();
        choices.slice(index, index + 5).forEach((choice, offset) => {
            row.addComponents(
                new ButtonBuilder()
                    .setCustomId(`mentor_teach_cmp_reward_${index + offset}`)
                    .setLabel(choice.label)
                    .setStyle(choice.type === 'style' ? ButtonStyle.Primary : ButtonStyle.Success)
            );
        });
        rows.push(row);
    }
    return rows;
}

// ---------- Merchants (from the Trello "Merchant" card) ----------
// Merchants are found in major cities. Only Earth shops sell food, shovels, and fishing rods.
// The city list is DERIVED from SPECIAL_SLOTS (the single source of truth for named locations,
// defined further down) so a city's space can only ever be written in ONE place — this used to be
// a separate literal table and the two drifted apart (Konats City, Sniper Hill, …).
// See `MERCHANT_CITIES` directly below the SPECIAL_SLOTS table for the derivation.

// List a planet's merchant cities for hint text, e.g. "North City (1), East City (6)".
function cityListText(location) {
    const cities = MERCHANT_CITIES[location];
    if (!cities) return null;
    return Object.entries(cities).map(([space, name]) => `${name} (${space})`).join(', ');
}

